    String statements = "CREATE TABLE IF NOT EXISTS zeppelin.albums(
" + "    title text PRIMARY KEY,
" + "    artist text,
" + "    year int
" + ");
" + "BEGIN BATCH" + "   INSERT INTO zeppelin.albums(title,artist,year) VALUES('The Impossible Dream EP','Carter the Unstoppable Sex Machine',1992);" + "   INSERT INTO zeppelin.albums(title,artist,year) VALUES('The Way You Are','Tears for Fears',1983);" + "   INSERT INTO zeppelin.albums(title,artist,year) VALUES('Primitive','Soulfly',2003);" + "APPLY BATCH;
" + "SELECT * FROM zeppelin.albums;";
    //When
    final InterpreterResult actual = interpreter.interpret(statements, intrContext);
    //Then
    assertThat(actual.code()).isEqualTo(Code.SUCCESS);
    assertThat(actual.message()).isEqualTo("title	artist	year
" + "The Impossible Dream EP	Carter the Unstoppable Sex Machine	1992
" + "The Way You Are	Tears for Fears	1983
" + "Primitive	Soulfly	2003
");
}

