    notebookRepo.checkpoint(TEST_NOTE_ID, "second commit");
    // see if commit is added
    List<Rev> notebookHistoryAfter = notebookRepo.history(TEST_NOTE_ID);
    assertThat(notebookHistoryAfter.size()).isEqualTo(initialCount + 1);
}

